### startDrill 
 function startDrill(){if(state.phase!=='PREP')return;state.phase='LIVE';state.seconds=90;state.score=100;let safe=routes.some(r=>checkPathSafety(r.points,hazards));if(!safe){state.score-=20;state.notice='NO SAFE ROUTES · SCORE AT RISK'}else state.notice='DRILL LIVE · EXTINGUISH ALL FIRES';if(sockets.filter(s=>s.type).length<2)state.score-=10;state.noticeTime=4;fires.forEach(f=>f.size=.72);civilians.forEach((c,i)=>{c.x=.46+i*.025;c.y=.48+i*.025;c.done=false;c.progress=0})}function spray(){let f=null,d=Infinity;for(const q of fires)if(q.size>0&&Math.hypot(q.x-player.x,q.y-player.y)<d){f=q;d=Math.hypot(q.x-player.x,q.y-player.y)}if(!f||d>.40)return;let ang=Math.atan2(f.y-player.y,f.x-player.x),dif=Math.atan2(Math.sin(ang-player.angle),Math.cos(ang-player.angle));if(Math.abs(dif)>.7)return;let ok=(f.type==='A'&&state.selected==='water'||f.type==='C'&&state.selected==='co2'||f.type==='K'&&state.selected==='wet'||f.type==='B'&&state.selected==='dry');if(!ok){if(state.selected==='water'&&(f.type==='C'||f.type==='K')){f.size=Math.min(1,f.size+.03);if(state.phase==='LIVE')state.score=Math.max(0,state.score-1)}return}f.size=Math.max(0,f.size-.004);if(Math.random()<.25){let p=P(player.x,player.y);particles.push({x:p.x,y:p.y,r:3*ui,color:'#b9e8ff'})}if(f.size===0&&!f.done){f.done=true;state.extinguished++;state.notice=f.label+' EXTINGUISHED';state.noticeTime=2.5}}

